/**
 * BULLETPROOF JEWELLERY LEAD QUALIFIER & VERIFIER
 * Tailored for UK Independent & Bespoke Jewellers (Hatton Garden, Birmingham JQ, Mayfair)
 * 1. Eliminates corporate call centers (0800, 0845, 0870, 0300) so you only reach atelier owners
 * 2. Normalizes phone numbers to standard UK format (+44...)
 * 3. Identifies UK mobiles (+447...) and generates 1-click WhatsApp links
 * 4. Accurately detects 'no_website' (Branch B) vs 'social_only' vs 'has_website' (Branch A)
 * 5. Generates consultative luxury outreach pitches with Veyra 3D Prototype
 */

const items = $input.all();
const config = $('Edit Fields').first().json || {};
const query = config.query || 'jewellers';
const location = config.location || 'london';
const minReviews = Number(config.min_reviews || 1);
const onlyNoWebsite = Boolean(config.only_no_website === true);

function detectTrade(name, category, q) {
  const text = `${name || ''} ${category || ''} ${q || ''}`.toLowerCase();
  if (text.includes('jewel') || text.includes('diamond') || text.includes('ring') || text.includes('gold') || text.includes('watch') || text.includes('gem') || text.includes('atelier')) return 'Jeweller';
  if (text.includes('roof')) return 'Roofer';
  if (text.includes('plumb')) return 'Plumber';
  if (text.includes('electr')) return 'Electrician';
  return 'Jeweller';
}

const validatedLeads = [];
const seenPhones = new Set();
const seenNames = new Set();

for (const item of items) {
  const place = item.json || {};
  const businessName = (place.title || place.name || '').trim();
  const rawPhone = (place.phoneNumber || place.phone || '').trim();
  const rawWebsite = (place.website || '').trim();
  const rating = Number(place.rating || 0);
  const reviewsCount = Number(place.ratingCount || place.user_ratings_total || 0);
  const address = (place.address || place.formatted_address || location).trim();
  const category = place.category || place.type || '';

  if (!businessName || !rawPhone) continue;
  if (reviewsCount < minReviews) continue;

  // Reject call centers & switchboards
  const cleanDigits = rawPhone.replace(/[^0-9]/g, '');
  if (
    cleanDigits.startsWith('0800') ||
    cleanDigits.startsWith('0808') ||
    cleanDigits.startsWith('0845') ||
    cleanDigits.startsWith('0870') ||
    cleanDigits.startsWith('0300') ||
    cleanDigits.startsWith('0345') ||
    cleanDigits.startsWith('44800') ||
    cleanDigits.startsWith('44845') ||
    cleanDigits.startsWith('44300')
  ) {
    continue;
  }

  // Normalize phone
  let formattedPhone = rawPhone.replace(/[^0-9+]/g, '');
  if (formattedPhone.startsWith('0')) {
    formattedPhone = '+44' + formattedPhone.substring(1);
  } else if (!formattedPhone.startsWith('+44')) {
    formattedPhone = '+44' + formattedPhone.replace(/^\+/, '');
  }
  const digitsOnly = formattedPhone.replace(/[^0-9]/g, '');

  // Deduplicate
  const nameKey = businessName.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (seenPhones.has(digitsOnly) || seenNames.has(nameKey)) continue;
  seenPhones.add(digitsOnly);
  seenNames.add(nameKey);

  // Classification
  let hasWebsite = true;
  let classification = 'has_website';

  if (!rawWebsite || rawWebsite === '' || rawWebsite.toLowerCase() === 'none' || rawWebsite.toLowerCase() === 'null') {
    hasWebsite = false;
    classification = 'no_website';
  } else {
    const w = rawWebsite.toLowerCase();
    if (
      w.includes('facebook.com') ||
      w.includes('instagram.com') ||
      w.includes('yell.com')
    ) {
      hasWebsite = false;
      classification = 'social_only';
    }
  }

  if (onlyNoWebsite && hasWebsite) continue;

  const isMobile = digitsOnly.startsWith('447');
  const channel = isMobile ? 'WhatsApp / SMS' : 'Landline / Direct Call';
  const trade = detectTrade(businessName, category, query);

  // Veyra Dynamic Prototype URL
  const veyraProtoUrl = `https://veyra-premium-3-d-jewellery-e-comme.vercel.app/?client=${encodeURIComponent(businessName)}`;

  // Tailored Luxury Jeweller Consultative Pitches
  let stage1Opener = '';
  let stage2Pitch = '';

  if (!hasWebsite) {
    // Branch B: No Website / Social Only
    stage1Opener = `Hi 👋 Came across ${businessName} on Instagram — stunning work. Had a quick search for your website to view the full collection, couldn't find one. Do you take all your bespoke commissions through WhatsApp / Instagram directly?`;
    stage2Pitch = `The pieces look exceptional. We put together a private interactive 3D concept prototype showing how ${businessName} could showcase custom rings and bespoke pieces with a dedicated online storefront: ${veyraProtoUrl} — take a look when you have a moment, no pressure at all.`;
  } else {
    // Branch A: Has Website
    stage1Opener = `Hi 👋 Came across ${businessName} — love the craftsmanship in your pieces. Had a quick look through your site, had a small question about how you showcase your bespoke commissions online if you have 30 seconds?`;
    stage2Pitch = `Loved looking through your catalogue. We noticed that high-ticket bespoke jewellery often loses that in-person luxury feel on standard mobile galleries. We built an interactive 3D concept prototype demonstrating how ${businessName}'s collection could be presented: ${veyraProtoUrl} — thought you might enjoy seeing it.`;
  }

  const followUp1 = `Hey — following up on ${businessName}. No pressure at all, just wanted to check if this landed and see what you thought of the 3D prototype.`;
  const followUpFinal = `Last one from me on this — if an elevated digital showroom isn't a priority right now, that's completely fair. If it ever is, the offer stands. All the best with the atelier!`;

  const waLink = isMobile ? `https://wa.me/${digitsOnly}?text=${encodeURIComponent(stage1Opener)}` : 'N/A';

  // Supabase Payload
  const supabasePayload = {
    name: 'Owner / Creative Director',
    business_name: businessName,
    phone: formattedPhone,
    website: hasWebsite ? rawWebsite : (classification === 'social_only' ? rawWebsite : null),
    service_interested: 'Interactive 3D Digital Atelier & Bespoke Commission Portal',
    notes: `${address} · ★${rating} (${reviewsCount} reviews) · Branch: ${classification === 'has_website' ? 'Branch A (Has Site)' : 'Branch B (No Site)'}`,
    status: 'New',
    source: 'google_maps_outreach',
    lead_type: 'jewellery',
    local_business_niche: 'Jeweller',
    outreach_category: classification,
    outreach_stage: 'uncontacted',
    prototype_url: veyraProtoUrl,
    whatsapp_direct_url: isMobile ? waLink : null,
    scraped_metadata: {
      address: address,
      rating: rating,
      reviews: reviewsCount,
      reviews_count: reviewsCount,
      rating_reviews: `${reviewsCount} (★${rating})`,
      trade: 'Jeweller',
      channel: channel,
      stage_1_opener: stage1Opener,
      stage_2_pitch: stage2Pitch,
      follow_up_1: followUp1,
      follow_up_final: followUpFinal,
      prototype_url: veyraProtoUrl
    }
  };

  validatedLeads.push({
    json: {
      "Business Name": businessName,
      "Phone": formattedPhone,
      "Channel": channel,
      "WhatsApp Link": waLink,
      "Reviews": reviewsCount,
      "Rating": rating,
      "Website": rawWebsite || 'None',
      "Address": address,
      "Trade": 'Jeweller',
      "Classification": classification,
      "Stage 1 Opener": stage1Opener,
      "Stage 2 Pitch": stage2Pitch,
      "Follow Up 1": followUp1,
      "Follow Up Final": followUpFinal,
      "Prototype URL": veyraProtoUrl,
      "Status": 'New',
      "supabase_payload": supabasePayload
    }
  });
}

return validatedLeads;
